done = {}
balance = {"KRW": 1_000_000, "USD": 0}

def exchange(key, krw, rate=1400):
    if key in done:                       # 같은 키 = 같은 요청 → 저장해 둔 답을 그대로
        return done[key] | {"replayed": True}
    usd = round(krw / rate, 2)
    balance["KRW"] -= krw; balance["USD"] += usd
    done[key] = {"usd": usd, "krw_left": balance["KRW"]}
    return done[key]

print(exchange("k-1", 140_000))
print(exchange("k-1", 140_000))           # 앱이 타임아웃 뒤 다시 보냄
