import re
PHONE = re.compile(r"01[016789]-?\d{3,4}-?\d{4}")

def mask(e):
    out = {}
    for k, v in e.items():
        if k == "phone": continue                      # 아예 버린다
        if k == "acct": v = "***-**-" + v[-4:]         # 끝 4자리만
        elif isinstance(v, str): v = PHONE.sub("[전화번호]", v)  # 자유 입력 칸 속 번호
        out[k] = v
    return out

print(mask({"event": "order_submit", "user_id": "u1", "phone": "010-1234-5678",
            "acct": "123-45-678901", "memo": "연락은 010-9876-5432"}))
